def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    change = v1 - v2

    return {
        "value": change,
        "trace": {
            "v1": v1,
            "v2": v2,
            "difference": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "currency"
            }
        }
    }
